    {
      "device": "M190",
      "comment": "ST10 latched fault"
    },
    {
      "device": "M191",
      "comment": "ST10 motor overload alarm"
    },
    {
      "device": "M199",
      "comment": "ST10 common fault"
    },
    {
      "device": "T11",
      "comment": "XY-1004 release pulse timer"
    }
  ],
  "rung_purposes": [
    {
      "rung": 1,
      "purpose": "Set motor overload alarm M191 when MOL-1001 (X13) trips."
    },
    {
      "rung": 2,
      "purpose": "Reset latched fault M190 when fault reset PB-0002 (X1) is pressed."
    },
    {
      "rung": 3,
      "purpose": "Set common fault M199 on latched fault M190, overload M191, or tripped E-stop X0."
    },
    {
      "rung": 4,
      "purpose": "Run conveyor motor M-1001 (Y10) in auto mode SS-0003 (X2) if no common fault M199."
    },
    {
      "rung": 5,
      "purpose": "Set pallet in position M100 when photo-eye PE-1001 (X10) detects pallet."
    },
    {
      "rung": 6,
      "purpose": "Latch stopper release solenoid XY-1004 (Y11) on release request RQ-1005 (X14) pulse."
    },
    {
      "rung": 7,
      "purpose": "Start 2.0 s timer T11 when stopper release solenoid XY-1004 (Y11) is energized."
    },
    {
      "rung": 8,
      "purpose": "Reset stopper release solenoid XY-1004 (Y11) when timer T11 completes."
    },
    {
      "rung": 9,
      "purpose": "End of ST10 program scan."
    }
  ],
  "suspicious": []
}
